// The standard bindings are generated by scripts/bindings/generate-web.mjs:
// Lasm.JS.Web (library/Lasm/JS/Web/*.lean), the whole web platform of @webref/idl, one module per spec;
// Lasm.JS.Node (library/Lasm/JS/Node/*.lean) from scripts/bindings/node.idl, the lowering of Node's API docs
// by scripts/bindings/node-api.mjs (whose --check needs the network and runs in web-bindings.yml). The
// committed files must be the generator's output.
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import * as nodeTier from '../scripts/bindings/node-tier2.mjs';
import * as serveTier from '../scripts/bindings/serve-tier2.mjs';
import { declarations, lowerHost, parseType, typeText } from '../scripts/bindings/serve-api.mjs';
import { libraryModules } from '../src/lasm-library.mjs';
import { lazyModules } from '../src/lazy-library.mjs';
import { join } from 'node:path';
import { referencedWebApis, targetRuntime, webAvailabilityErrors } from '../src/web-availability.mjs';

const root = fileURLToPath(new URL('../', import.meta.url));
const webDir = new URL('../library/Lasm/JS/Web/', import.meta.url);
const webModules = JSON.parse(readFileSync(new URL('modules.json', webDir), 'utf8')).modules;
const moduleSource = m => readFileSync(`${root}library/${m.replaceAll('.', '/')}.lean`, 'utf8');
const importsOf = m => [...moduleSource(m).matchAll(/^import (Lasm\.\S+)$/gm)].map(x => x[1]);

test('the committed Lasm.JS.Web, Lasm.JS.Node, Lasm.JS.Deno and Lasm.JS.Bun modules are the generator output', () => {
  const r = spawnSync(process.execPath, [fileURLToPath(new URL('../scripts/bindings/generate-web.mjs', import.meta.url)), '--check'], { encoding: 'utf8' });
  assert.equal(r.status, 0, r.stdout + r.stderr);
});

test('Lasm.JS.Web is every spec of @webref/idl: each spec with an interface has its module', () => {
  const specs = readdirSync(new URL('../node_modules/@webref/idl/', import.meta.url)).filter(f => f.endsWith('.idl'));
  assert.ok(webModules.length > 300, `${webModules.length} modules`);
  for (const [spec, module] of [['fetch', 'Fetch'], ['dom', 'Dom'], ['html', 'Html'], ['IndexedDB', 'IndexedDB'], ['webgpu', 'Webgpu'], ['url', 'Url'], ['hr-time', 'HrTime']]) {
    assert.ok(specs.includes(spec + '.idl'));
    assert.ok(webModules.includes(`Lasm.JS.Web.${module}`), `${spec} → Lasm.JS.Web.${module}`);
  }
  // No umbrella (0.3-18): every spec module is compiled on first import.
  assert.ok(!libraryModules.includes('Lasm.JS.Web'));
});

test('every generated module is a shipped library module, in import order, and Lasm.JS.Web imports only itself', () => {
  for (const tier of ['Node', 'Deno', 'Bun']) {
    const generated = readdirSync(new URL(`../library/Lasm/JS/${tier}/`, import.meta.url)).map(f => `Lasm.JS.${tier}.${f.replace(/\.lean$/, '')}`);
    for (const m of [...generated, `Lasm.JS.${tier}`]) assert.ok(libraryModules.includes(m), `${m} is not in src/lasm-library.mjs libraryModules`);
    for (const m of generated) for (const imported of importsOf(m))
      assert.ok(libraryModules.indexOf(imported) < libraryModules.indexOf(m), `${m} imports ${imported}, which comes later`);
  }
  const order = JSON.parse(readFileSync(new URL('modules.json', webDir), 'utf8')).modules;
  for (const m of webModules) {
    // Compiled with the prefix (the core the templates use), or on first import (src/lazy-library.mjs).
    assert.ok(libraryModules.includes(m) || lazyModules(libraryModules).includes(m), `${m} is neither compiled with the prefix nor on first import`);
    for (const imported of importsOf(m)) {
      assert.ok(imported === 'Lasm.JS.Web.Support' || order.indexOf(imported) < order.indexOf(m), `${m} imports ${imported}, which comes later`);
      assert.ok(/^Lasm\.JS\.Web(\.|$)/.test(imported), `${m} imports ${imported}, outside Lasm.JS.Web`);
      // A module compiled with the prefix never needs one compiled on first import.
      if (libraryModules.includes(m)) assert.ok(libraryModules.includes(imported), `${m} (prebuilt) imports ${imported} (compiled on first import)`);
    }
  }
  // The templates and the example apps need only prebuilt web modules.
  const walk = dir => readdirSync(dir, { withFileTypes: true }).flatMap(e => ['node_modules', '.lake', 'dist'].includes(e.name) ? []
    : e.isDirectory() ? walk(join(dir, e.name)) : e.name.endsWith('.lean') ? [join(dir, e.name)] : []);
  for (const file of [...walk(`${root}templates`), ...walk(`${root}examples`)])
    for (const [, m] of readFileSync(file, 'utf8').matchAll(/^import (Lasm\.JS\.Web\.\S+)$/gm))
      assert.ok(libraryModules.includes(m), `${file.slice(root.length)} imports ${m}, which is not prebuilt (src/lasm-library.mjs eagerWebRoots)`);
});

test('handle types are per spec (Lasm.JS.Web.Types.<Spec>), importing only their parents\' types', () => {
  for (const [spec, name] of [['Dom', 'Element'], ['Fetch', 'Request'], ['Html', 'HTMLVideoElement'], ['Webgpu', 'GPUDevice'], ['IndexedDB', 'IDBDatabase']])
    assert.match(moduleSource(`Lasm.JS.Web.Types.${spec}`), new RegExp(`^structure ${name} `, 'm'));
  for (const m of webModules.filter(m => m.startsWith('Lasm.JS.Web.Types.')))
    for (const i of importsOf(m)) assert.ok(i === 'Lasm.JS.Web.Support' || i.startsWith('Lasm.JS.Web.Types.'), `${m} imports ${i}`);
  // A program importing Fetch builds no HTML.
  assert.ok(!importsOf('Lasm.JS.Web.Fetch').includes('Lasm.JS.Web.Html'));
});

test('a nullable Value result is requested as data, so that null is none', () => {
  // A reference-mode result is a reference for null too: getContext of an unsupported
  // context id would be some (a reference to null) if it were requested as Option Value.
  const html = moduleSource('Lasm.JS.Web.Html');
  assert.match(html, /def HTMLCanvasElement\.getContext [^\n]*: IO \(Option Value\) := Internal\.api "Lasm\.JS\.Web\.HTMLCanvasElement\.getContext" do\n {2}let r ← self\.val\.callMethod "getContext" \(Internal\.args #\[toJS contextId, options\]\) Data\n {2}Internal\.optionalValue r/);
  assert.doesNotMatch(html, /\) \(Option Value\)$/m, 'Html.lean requests a result as Option Value');
});

test('Window\'s members are globals and methods; a spec\'s partials are in its module', () => {
  const html = moduleSource('Lasm.JS.Web.Html');
  assert.match(html, /^@\[macro_inline\] def document : IO Document/m);
  assert.match(html, /^@\[macro_inline\] def Window\.document \(self : Window\) : IO Document/m);
  assert.match(moduleSource('Lasm.JS.Web.Geolocation'), /^@\[macro_inline\] def Navigator\.geolocation /m);
  assert.match(moduleSource('Lasm.JS.Web.Fetch'), /^@\[macro_inline\] def fetch /m);
});

test('lasm build --target refuses a web API the target lacks (src/web-availability.mjs)', () => {
  // A call site's C holds the binding's full name (Internal.api "…"), as a string literal.
  const c = 'x = lean_mk_string_unchecked("Lasm.JS.Web.document", 20, 20); y = lean_mk_string_unchecked("Lasm.JS.Web.notAnApi", 20, 20);';
  const refs = referencedWebApis([c]);
  assert.deepEqual(refs, ['Lasm.JS.Web.document']);
  const [error] = webAvailabilityErrors(refs, 'workers');
  assert.match(error, /^Lasm\.JS\.Web\.document \(api\.Window\.document\) is not available on --target workers \(Cloudflare Workers/);
  assert.match(error, /It is available on browsers \(Chromium 153, Firefox 155, Safari 26\.6\)/);
  assert.deepEqual(webAvailabilityErrors(refs, 'browser'), []);
  assert.equal(targetRuntime('lambda'), 'node');
  assert.equal(targetRuntime('supabase-edge'), 'deno');
  // fetch is everywhere: not in the table of APIs missing somewhere.
  assert.deepEqual(referencedWebApis(['"Lasm.JS.Web.fetch"']), []);
});

test('every web binding is macro_inline data: each parameter occurs exactly once in its body', () => {
  let checked = 0;
  for (const m of webModules) {
    const text = moduleSource(m);
    for (const [, header, body] of text.matchAll(/^@\[macro_inline\] (def [^\n]*?:= Internal\.api "[^"]+" do)\n((?:  [^\n]*\n)+)/gm)) {
      const params = [...header.matchAll(/\((«[^»]+»|[A-Za-z_][A-Za-z0-9_']*) :/g)].map(x => x[1]);
      const code = body.replace(/"(?:[^"\\]|\\.)*"/g, '""');
      for (const p of params) {
        const uses = code.match(new RegExp(`(?<![A-Za-z0-9_'.«])${p.replace(/[«»]/g, x => '\\' + x)}(?![A-Za-z0-9_'»])(?! :=)`, 'g'))?.length ?? 0;
        assert.equal(uses, 1, `${m}: ${header.slice(0, 80)}: ${p} occurs ${uses} times`);
      }
      checked++;
    }
  }
  assert.ok(checked > 10000, `${checked} bindings checked`);
});

// Lasm.JS.Deno and Lasm.JS.Bun (scripts/bindings/serve-api.mjs lowers the runtimes'
// TypeScript declarations; its --check needs the network and runs in web-bindings.yml).
test('every Lasm.JS.Deno and Lasm.JS.Bun selection is generated, and no exclusion is', () => {
  const { surface } = JSON.parse(readFileSync(new URL('../scripts/bindings/serve-surface.json', import.meta.url), 'utf8'));
  for (const h of serveTier.hosts) {
    const s = surface[h.name];
    assert.ok(s, `${h.name} is missing from the generated surface`);
    assert.equal(s.global, h.global);
    for (const f of Object.keys(h.functions)) assert.ok(s.functions.includes(f), `${h.global}.${f} is not generated`);
    for (const d of h.declarations.filter(d => d.as === 'interface')) {
      const members = s.interfaces[d.lean ?? d.name.split('.').at(-1)];
      assert.ok(members, `${d.name} is not generated`);
      for (const e of Object.keys(d.exclude ?? {})) assert.ok(!members.includes(e), `${d.name}.${e} is excluded but generated`);
    }
  }
  const idl = readFileSync(new URL('../scripts/bindings/deno.idl', import.meta.url), 'utf8');
  assert.match(idl, /Deno\.serve\(options: ServeVsockOptions, handler: ServeHandler<Deno\.VsockAddr>\): @experimental in its declaration/);
});

/** A host of serve-tier2.mjs's shape over one synthetic declaration file. */
const host = (extra = {}) => ({
  name: 'Rt', global: 'Rt', files: ['rt.d.ts'], instantiate: { A: 'Addr' }, notSelected: { Disposable: 'not needed' },
  functions: { serve: { module: 'Serve', overloads: {
    'handler: Handler<Rt.Addr>': { lower: true },
    'options: Opts | (Opts & Tls), handler: Handler<Rt.Addr>': { lower: true, split: { options: ['options', 'tlsOptions'] } },
    'path: string': { exclude: 'outside the cut' } } } },
  declarations: [
    { name: 'Handler', as: 'callback', module: 'Serve' },
    { name: 'Server', as: 'interface', module: 'Serve', exclude: { secret: 'not public' } },
    { name: 'Opts', as: 'dictionary', module: 'Serve' },
    { name: 'Tls', as: 'dictionary', module: 'Serve' },
    { name: 'Addr', as: 'interface', module: 'Serve' },
  ],
  intersections: { 'Opts & Tls': 'TlsOpts' },
  integers: { 'Opts.port': { type: 'unsigned short', quote: 'The port to listen on.' } },
  typeNames: { Request: 'Request', Response: 'Response', unknown: 'any' },
  ...extra,
});
const source = `
declare namespace Rt {
  /** A handler. */
  export type Handler<A extends Rt.Addr = Rt.Addr> = (
    request: Request,
    info: A,
  ) => Response | Promise<Response>;
  export interface Server<A = Addr> extends Disposable {
    /** Settles when closed. */
    finished: Promise<void>;
    readonly port: number | undefined;
    stop(force?: boolean): Promise<void>;
    secret(): string;
    /** @experimental */
    beta(): void;
  }
  export interface Opts {
    /** The port to listen on. */
    port?: number;
    hostname?: "0.0.0.0" | "localhost" | (string & {});
    mode?: "fast" | "slow";
    onError?: (this: Server, error: unknown) => Response | Promise<Response> | void;
    id?: string | null;
  }
  export interface Tls { cert: string; key: string; }
  export interface Addr { transport: "tcp" | "udp"; hostname: string; }
  /** Serves. */
  export function serve(handler: Handler<Rt.Addr>): Server<Rt.Addr>;
  export function serve(
    options: Opts | (Opts & Tls),
    handler: Handler<Rt.Addr>,
  ): Server<Rt.Addr>;
  export function serve(path: string): Server;
  /** @experimental **UNSTABLE** */
  export function serve(sock: number): Server;
}
`;
const lower = (h = host(), text = source) => lowerHost(h, [{ file: 'rt.d.ts', text }]);

test('serve-api reads declarations: namespaces, interfaces, type aliases and function overloads', () => {
  const d = declarations(source, 'rt.d.ts');
  assert.deepEqual(d.map(x => `${x.kind} ${x.name}`), ['type Rt.Handler', 'interface Rt.Server', 'interface Rt.Opts', 'interface Rt.Tls',
    'interface Rt.Addr', 'function Rt.serve', 'function Rt.serve', 'function Rt.serve', 'function Rt.serve']);
  assert.match(d[0].doc, /A handler/);
  assert.equal(typeText(parseType('"a" | (string & {}) | Promise<Response[]> | ((x: number) => void)')),
    '"a" | string & {} | Promise<Response[]> | ((x: number) => void)');
  assert.throws(() => parseType('T extends U ? A : B'), /conditional types are not lowered/);
});

test('serve-api lowers by its rules', () => {
  const { idl, excluded } = lower();
  // Functions: one overload per union alternative of a split parameter, named for it.
  assert.match(idl, /Rt_Server serve\(Rt_Handler handler\);/);
  assert.match(idl, /Rt_Server serve\(Rt_Opts options, Rt_Handler handler\);/);
  assert.match(idl, /Rt_Server serve\(Rt_TlsOpts tlsOptions, Rt_Handler handler\);/);
  // A callback: T | Promise<T> is Promise<T>; the generic parameter is its instantiation.
  assert.match(idl, /callback Rt_Handler = Promise<Response> \(Request request, Rt_Addr info\);/);
  // Handles: readonly attributes, nullable from undefined, the experimental member left out.
  assert.match(idl, /readonly attribute Promise<undefined> finished;/);
  assert.match(idl, /readonly attribute double\? port;/);
  assert.match(idl, /Promise<undefined> stop\(optional boolean force\);/);
  assert.doesNotMatch(idl, /secret\(|beta\(/);
  // Dictionaries: integers narrowed, literal unions enums, literals with any string DOMString,
  // `this` dropped and void dropped from a callback's result, an optional member's undefined dropped.
  assert.match(idl, /unsigned short port;/);
  assert.match(idl, /DOMString hostname;/);
  assert.match(idl, /Rt_OptsMode mode;/);
  assert.match(idl, /enum Rt_OptsMode \{ "fast", "slow" \};/);
  assert.match(idl, /callback Rt_OptsOnError = Promise<Response> \(any error\);/);
  assert.match(idl, /void alternatives dropped/);
  assert.match(idl, /DOMString\? id;/);
  assert.match(idl, /dictionary Rt_TlsOpts : Rt_Opts \{[^}]*required DOMString cert;[^}]*required DOMString key;/);
  assert.deepEqual(excluded.map(([w]) => w).sort(), ['Rt.serve(path: string)', 'Rt.serve(sock: number)', 'Server.beta', 'Server.secret']);
});

test('serve-api fails on what its selection does not decide', () => {
  // An overload neither lowered nor excluded.
  const h1 = host();
  delete h1.functions.serve.overloads['path: string'];
  assert.throws(() => lower(h1), /neither lowers nor excludes/);
  // A member neither lowered nor excluded, where the selection names only some.
  const h2 = host();
  h2.declarations = h2.declarations.map(d => d.name === 'Opts' ? { ...d, compose: [{ from: 'Opts', only: ['port'] }] } : d);
  assert.throws(() => lower(h2), /not in `only` and not excluded/);
  // An exclusion of a member that does not exist.
  const h3 = host();
  h3.declarations = h3.declarations.map(d => d.name === 'Server' ? { ...d, exclude: { ...d.exclude, gone: 'x' } } : d);
  assert.throws(() => lower(h3), /Server\.gone is excluded but not a member/);
  // An integer whose doc comment no longer says what the narrowing quotes.
  assert.throws(() => lower(host(), source.replace('The port to listen on.', 'A port.')), /no longer says/);
  // A second instantiation of a generic.
  const h4 = host();
  h4.functions.serve.overloads = { ...h4.functions.serve.overloads, 'handler: Handler<Rt.Other>': { lower: true } };
  delete h4.functions.serve.overloads['handler: Handler<Rt.Addr>'];
  assert.throws(() => lower(h4, source.replace('serve(handler: Handler<Rt.Addr>)', 'serve(handler: Handler<Rt.Other>)')), /second instantiation/);
  // A type that is neither selected nor named.
  assert.throws(() => lower(host(), source.replace('request: Request,', 'request: Bogus,')), /neither selected nor in serve-tier2.mjs typeNames/);
  // A selected overload that is experimental.
  const h5 = host();
  h5.functions.serve.overloads['sock: number'] = { lower: true };
  assert.throws(() => lower(h5), /@experimental, but serve-tier2.mjs selects it/);
});

test('every generated enum has exactly its WebIDL values, as abbrevs over the string (0.3-17)', async () => {
  const { createRequire } = await import('node:module');
  const require = createRequire(import.meta.url);
  const webidl2 = require('webidl2');
  const idlDir = new URL('../node_modules/@webref/idl/', import.meta.url);
  const enums = new Map();
  for (const f of readdirSync(idlDir).filter(f => f.endsWith('.idl')))
    for (const d of webidl2.parse(readFileSync(new URL(f, idlDir), 'utf8'))) if (d.type === 'enum') enums.set(d.name, d.values.map(v => v.value));
  let checked = 0;
  for (const m of webModules.filter(m => m.startsWith('Lasm.JS.Web.Types.'))) {
    const text = moduleSource(m);
    for (const [, name] of text.matchAll(/^\/-- `enum (\S+)` /gm)) {
      const values = enums.get(name);
      assert.ok(values, `${m}: ${name} is not a WebIDL enum`);
      const generated = [...text.matchAll(new RegExp(`^@\\[match_pattern\\] abbrev ${name}\\.\\S+ : ${name} := \\.unsafeOfString ("(?:[^"\\\\]|\\\\.)*")$`, 'gm'))].map(x => JSON.parse(x[1]));
      assert.deepEqual(generated, values, `${name}'s values`);
      checked++;
    }
  }
  assert.ok(checked > 300, `${checked} enums checked`);
});
